  if (pal < 0.5) col = h < 0.18 ? mix(vec3(0.3, 0.02, 0.0), vec3(0.95, 0.22, 0.02), h / 0.18) : h < 0.45 ? mix(vec3(0.95, 0.22, 0.02), vec3(1.0, 0.6, 0.1), (h - 0.18) / 0.27) : mix(vec3(1.0, 0.6, 0.1), vec3(1.0, 0.95, 0.75), min(1.0, (h - 0.45) / 0.4));
